# tools/r171_splice.py - R171, 5 patches: Appendices
# K, L and M (DMG pp.221-224) - the magical
# substance word lists, the conjured animals
# table and the summoned monsters tables. A new
# header-only layer, rules/klm.h (the grenade.h
# pattern: the caller rolls and selects; these
# are support tables for the conjure and summon
# spell effects).
#
# (1) rules/klm.h: APPENDIX K - the appearance
#     and consistency list (10: bubbling, cloudy,
#     effervescent, fuming, oily, smoky, syrupy,
#     vaporous, viscous, watery); the
#     transparency list (10 with the printed
#     parentheticals: clear, flecked, layered,
#     luminous, opaline, phosphorescent,
#     rainbowed, ribboned, translucent,
#     variegated); the color list - 74 words in
#     11 printed groups (METALLIC 6, WHITE 4,
#     GRAY 3, BROWN 6, BLACK 5, VIOLET 10,
#     YELLOW 10, RED 16, GREEN 3, BLUE 6,
#     ORANGE 5); the taste and/or odor list (28,
#     acidic through watery); the use with
#     Appendix I dungeon dressing prose.
#     APPENDIX L - the conjure animals prose
#     (fractional hit point costs charged
#     against the total, random selection where
#     several possibilities exist, the caster
#     cannot specify); the hit dice category
#     tables cell by cell - category 1 (5 rows:
#     baboon 1 1/4, dog wild 1 1/4, flightless
#     bird 1/2, jackal 1/2, rat giant 1/2),
#     category 2 (4 rows: badger 1 1/2,
#     flightless bird 2, herd animal 2, horse
#     wild 2), category 3 (15 rows: axe beak,
#     badger giant, boar/warthog, camel, cattle
#     wild 2 1/2, dog war 2 1/2, flightless
#     bird, goat giant 3 1/4, hyena, lion
#     mountain 3 1/4, lynx giant 2 1/2, mule,
#     stag, wolf 2 1/2, wolverine), category 4
#     (13 rows: ape 4 1/4, bear black 3 3/4,
#     beaver giant, boar wild 3 3/4, bull,
#     eagle giant, Irish deer, jaguar 4 1/4,
#     leopard 3 1/2, owl giant, ram giant,
#     weasel giant 3 3/4, wolf dire 3 3/4); the
#     higher roster (20 printed animal names);
#     the whale 36 hit dice cost cap; the water
#     note (only swimmers and flying ones).
#     APPENDIX M - the summoned monsters prose
#     (if the summoner is evil, the monster in
#     parentheses may be used; the DM may select
#     and appoint numbers); the 7 land tables
#     (I 6 rows, II 6, III 12, IV 12, V 12, VI
#     16, VII 34) and the 13 water tables
#     (fresh/salt for summonings I through VII,
#     VI shared), every band, name and evil
#     alternate pinned. (2) the regtest include.
#     (3) the R171 audit: every printed cell
#     pinned - CENSUS 89. (4)-(5) the gap
#     report.
#
# JUDGMENTs: (a) the re-upload interleaves the
# Appendix K lists with the Appendix J herbs
# material (p.220, a separate open box) and
# drops rows; the K lists were cell-verified
# against the 1eonline.info compilation (the
# repo-trusted source, the R146 precedent),
# which agrees with the upload wherever the
# upload is legible. (b) the Appendix L
# 5-and-up section: the re-upload interleaves
# its band columns beyond confident
# reconstruction; the printed animal roster, the
# whale cap and the water note are pinned, and
# the band columns are recorded as OCR debt
# (open finding). (c) the Appendix M water
# tables for summonings II through VI are
# dropped wholesale by the re-upload; pinned
# from the trusted compilation, which agrees
# with the upload cell for cell on the I and
# VII water tables the upload does show.
#
# Idempotent: safe to run twice; a silent run means the
# paste was truncated - this tail ALWAYS prints. An assert
# follows EVERY patch (the R142 lesson). ZERO backslash
# characters in this file; no content string embeds a
# literal apostrophe (the R133b + R147 lessons).
# Commit: "R171: appendices K L and M pinned - the p.221-224
# substance lists, conjured animals and summoned monsters
# (census 89)"
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
NL = chr(10)
BS = chr(92)
applied, already, fails = [], [], []

def rd(p):
    with open(os.path.join(ROOT, p), encoding="latin-1") as f:
        return f.read()

def wr(p, s):
    with open(os.path.join(ROOT, p), "w", encoding="latin-1") as f:
        f.write(s)

def patch(p, old, new, tag, marker):
    s = rd(p)
    if marker in s:
        already.append(tag)
        return
    n = s.count(old)
    if n != 1:
        fails.append(tag + ": anchor count " + str(n)
                     + " (expected 1)")
        return
    wr(p, s.replace(old, new))
    applied.append(tag)

def create(p, text, tag, marker):
    fp = os.path.join(ROOT, p)
    if os.path.exists(fp):
        s = rd(p)
        if marker in s:
            already.append(tag)
            return
        fails.append(tag + ": exists without the marker")
        return
    wr(p, text)
    applied.append(tag)

